def copy_roles(apps, schema_editor):
    """Sales S0: each member's and invitation's single role becomes their first role link."""
    WorkspaceMember = apps.get_model("workspaces", "WorkspaceMember")
    WorkspaceMemberRole = apps.get_model("workspaces", "WorkspaceMemberRole")
    Invitation = apps.get_model("workspaces", "Invitation")
    InvitationRole = apps.get_model("workspaces", "InvitationRole")
    WorkspaceMemberRole.objects.bulk_create(
        [
            WorkspaceMemberRole(workspace_id=m.workspace_id, member_id=m.pk, role_id=m.role_id)
            for m in WorkspaceMember.objects.exclude(role_id=None).only("pk", "workspace_id", "role_id")
        ],
        ignore_conflicts=True,
    )
    InvitationRole.objects.bulk_create(
        [
            InvitationRole(workspace_id=i.workspace_id, invitation_id=i.pk, role_id=i.role_id)
            for i in Invitation.objects.exclude(role_id=None).only("pk", "workspace_id", "role_id")
        ],
        ignore_conflicts=True,
    )


def copy_roles_back(apps, schema_editor):
    WorkspaceMember = apps.get_model("workspaces", "WorkspaceMember")
    WorkspaceMemberRole = apps.get_model("workspaces", "WorkspaceMemberRole")
    Invitation = apps.get_model("workspaces", "Invitation")
    InvitationRole = apps.get_model("workspaces", "InvitationRole")
    for link in WorkspaceMemberRole.objects.order_by("created_at"):
        WorkspaceMember.objects.filter(pk=link.member_id, role_id=None).update(role_id=link.role_id)
    for link in InvitationRole.objects.order_by("created_at"):
        Invitation.objects.filter(pk=link.invitation_id, role_id=None).update(role_id=link.role_id)


